    ui: { labelFee: 'Stała cena projektu', labelPlannedHours: 'Godziny pracy', labelRevisions: 'Rundy poprawek', labelRevisionHours: 'Godziny na poprawkę', labelMeetings: 'Spotkania', labelMeetingHours: 'Godziny na spotkanie', labelDirectCosts: 'Bezpośrednie koszty projektu', labelTargetRate: 'Docelowa stawka godzinowa', labelDelay: 'Scenariusz dodatkowych godzin', labelEffectiveRate: 'Rzeczywista stawka godzinowa', labelAfterCosts: 'Cena po kosztach bezpośrednich', labelTotalHours: 'Realistyczne godziny projektu', labelHiddenHours: 'Dodatkowe godziny', labelBufferedRate: 'Stawka ze scenariuszem', labelRecommendedFee: 'Cena dla osiągnięcia celu', labelFeeGap: 'Różnica do negocjacji', labelPlanned: 'Planowana praca', labelHidden: 'Dodatkowa praca', labelWorkloadLedger: 'Rozliczenie godzin', labelHandsOn: 'Praca wykonawcza', labelRevisionTime: 'Czas poprawek', labelMeetingTime: 'Czas spotkań', labelScenarioTotal: 'Z marginesem scenariusza', labelBuffer: 'Scenariusz', labelCurrency: 'Waluta', labelProjectMath: 'Kalkulacja projektu', titleInputs: 'Pokaż niewidoczną pracę', titleHiddenWork: 'Dodatkowa praca', titleResults: 'Twój projekt w godzinach', statusBelow: 'Poniżej celu o', statusAtOrAbove: 'Na poziomie lub powyżej celu o', statusNoHours: 'Dodaj co najmniej jedną godzinę projektu, aby zobaczyć stawkę.', noteBeforeTax: 'Przed podatkami. Korzysta tylko z podanych danych i działa w przeglądarce.', btnBuffer0: 'Bez marginesu', btnBuffer10: '+10%', btnBuffer25: '+25%', btnBuffer50: '+50%' },
    faq: [{ question: 'Co pokazuje rzeczywista stawka godzinowa?', answer: 'Pokazuje, ile z ceny stałej zostaje za godzinę po odjęciu kosztów bezpośrednich oraz dodaniu pracy, poprawek i spotkań.' }, { question: 'Jakie godziny uwzględnić?', answer: 'Zacznij od godzin wykonawczych, a następnie dodaj realistyczne poprawki i spotkania, aby ujawnić pomijany czas.' }, { question: 'Jak działa margines?', answer: 'Wybrany procent zostaje dodany do wszystkich godzin projektu. To scenariusz dodatkowej pracy, a nie prognoza terminu.' }, { question: 'Jak obliczana jest zalecana cena?', answer: 'Koszty bezpośrednie są dodawane do łącznej liczby godzin pomnożonej przez stawkę docelową. To osobista granica negocjacji.' }],
