export function getLocalizedProjectFeeContent(locale: string) {
  const copy = data[locale];
  if (!copy) throw new Error(`Missing project fee locale: ${locale}`);
  return createProjectFeeContent({
    locale,
    slug: copy.slug,
    title: copy.title,
    description: copy.description,
    ui: { ...copy.ui, numberLocale: copy.numberLocale },
    faq: copy.faq,
    howTo: copy.howTo,
    seo: copy.seo,
    bibliography,
  });
}
